function renderEditor(id){const original=id?itemById(id):null;if(id&&!original)return missing();draft=original?clone(original):{name:'未命名图纸',description:'',author:'',size:29,grid:Array.from({length:29},()=>Array(29).fill(null)),palette:[]};dirty=false;let tool='pen',selected=null,history=[],future=[],stroke=false,lastCell=null,panning=null;const currentPalette=()=>paletteMap(draft);const standard=window.MARD_PALETTE.map(c=>({code:'mard-'+c.code,displayCode:c.code,hex:c.hex,name:c.code,standard:true}));const working=draft.palette.filter(c=>!c.standard),quickCodes=new Set(stats(draft).entries.map(([code])=>code));selected=draft.palette[0]?.code||standard.find(c=>c.displayCode==='H7').code;
app.innerHTML='<a class="back" href="#home">← 返回图纸列表</a><section class="hero"><div><h1>'+(original?'编辑图纸':'新建图纸')+'</h1><p>'+(original?'以「'+esc(original.name)+'」为底稿，保存时可覆盖当前图纸或另存为新图。':'从空白板开始，选择颜色后逐格绘制。')+'</p></div><div class="actions"><span class="draftState" id="draftState">'+(canWrite?'未保存的编辑副本':'线上试改 · 本地才能保存源码')+'</span><button id="export">导出图片</button><button id="save" class="primary" '+(!canWrite?'disabled title="请在本地预览保存到源码"':'')+'>保存图纸</button></div></section><div class="editorLayout"><aside class="editorSide"><label class="field">图纸名称<input id="name" maxlength="120" value="'+esc(draft.name)+'"></label><label class="field">作者名<input id="author" maxlength="60" placeholder="填写后显示在图纸右上角" value="'+esc(draft.author||'')+'"></label><label class="field">说明<textarea id="description" maxlength="2000">'+esc(draft.description)+'</textarea></label><label class="field">板型<select id="size">'+[...new Set([29,52,78,104,draft.size])].sort((a,b)=>a-b).map(n=>'<option value="'+n+'" '+(n===draft.size?'selected':'')+'>'+n+' × '+n+(n===33?'（A 版图案）':'')+'</option>').join('')+'</select></label><h3>绘制工具</h3><div class="toolGrid">'+[['pen','画笔'],['erase','橡皮'],['fill','填充'],['pick','吸管'],['hand','移动']].map(([id,name])=>'<button data-tool="'+id+'" class="'+(id==='pen'?'on':'')+'">'+name+'</button>').join('')+'</div><div class="actions"><button id="undo" disabled>撤销</button><button id="redo" disabled>重做</button></div><p class="muted">放大后可精确编辑。选择“移动”可拖动画布。</p><hr><div id="editStats"></div></aside><section class="surface">'+previewToolbar(true)+'<div class="viewport" id="viewport"><div class="canvasWrap"><canvas class="board" id="board" aria-label="可编辑拼豆画布"></canvas></div></div><div class="canvasStatus" id="cellStatus">选择颜色，在格子上点击或拖动绘制。</div></section><aside class="editorSide colorsSide"><h3>图纸用色</h3><div class="chosenColor" id="chosenColor"></div><div class="paletteGrid quickPalette" id="quickPalette" aria-label="图纸快捷颜色"></div><p class="muted">选择颜色后点击格子；选择空白可擦除豆子。</p><details class="moreColors"><summary>添加其他颜色 · 291 色</summary><input class="paletteSearch" id="paletteSearch" aria-label="搜索颜色" placeholder="搜索色号，例如 A8"><div class="paletteGrid" id="paletteGrid"></div></details><a class="plainLink" href="palette-221.html" target="_blank">查看完整色卡 ↗</a></aside></div>';
const {canvas,redraw}=attachCanvas(draft,true),viewport=$('#viewport');function mark(){dirty=true;$('#draftState').textContent='有未保存的修改'}function update(){redraw();renderQuickPalette();const s=stats(draft);$('#editStats').innerHTML='<p><b>'+s.total+'</b> 颗 · <b>'+s.entries.length+'</b> 色</p>';$('#undo').disabled=!history.length;$('#redo').disabled=!future.length}
function snapshot(){history.push(clone(draft.grid));if(history.length>50)history.shift();future=[]}function setSelected(code){selected=code;const c=currentPalette()[code]||standard.find(c=>c.code===code);$('#chosenColor').innerHTML=c?'<span class="dot" style="background:'+c.hex+'"></span><b>'+esc(label(c))+'</b> · '+c.hex:'<span class="dot blankSwatch"></span><b>空白 / 橡皮</b>';document.querySelectorAll('[data-color]').forEach(b=>{const on=(b.dataset.color||null)===selected;b.classList.toggle('chosen',on);b.setAttribute('aria-pressed',String(on))})}
function chooseColor(code){setSelected(code);if(tool!=='fill')setTool('pen')}
function colorButton(c){return '<button class="colorBtn '+(selected===c.code?'chosen':'')+'" data-color="'+c.code+'" aria-pressed="'+(selected===c.code)+'" style="background:'+c.hex+';color:'+ink(c.hex)+'" title="'+esc(label(c))+'">'+esc(label(c))+'</button>'}
function bindColors(container){container.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>chooseColor(b.dataset.color||null))}
function renderQuickPalette(){stats(draft).entries.forEach(([code])=>quickCodes.add(code));const map=currentPalette(),colors=[...quickCodes].map(code=>map[code]).filter(Boolean).sort((a,b)=>label(a).localeCompare(label(b),'en',{numeric:true}));$('#quickPalette').innerHTML='<button class="colorBtn blankSwatch '+(selected===null?'chosen':'')+'" data-color="" aria-pressed="'+(selected===null)+'" title="空白，相当于橡皮">空白</button>'+colors.map(colorButton).join('');bindColors($('#quickPalette'))}
function renderPalette(){const q=$('#paletteSearch').value.trim().toUpperCase(),all=[...working,...standard].filter(c=>(label(c)+' '+c.hex).toUpperCase().includes(q));$('#paletteGrid').innerHTML=all.map(colorButton).join('');bindColors($('#paletteGrid'))}
$('#paletteSearch').oninput=renderPalette;renderPalette();setSelected(selected);function setTool(next){tool=next;if(tool==='erase')setSelected(null);stroke=false;panning=null;document.querySelectorAll('[data-tool]').forEach(x=>{const on=x.dataset.tool===tool;x.classList.toggle('on',on);x.setAttribute('aria-pressed',String(on))});canvas.style.cursor=tool==='hand'?'grab':tool==='pen'?'default':'crosshair';$('#cellStatus').textContent=tool==='hand'?'按住图纸拖动位置，不会修改豆子。':'选择颜色后点击格子换色，也可以按住连续绘制。'}document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));setTool('pen');
function ensureColor(){if(selected===null)return;if(!draft.palette.some(c=>c.code===selected)){draft.palette.push(clone(standard.find(c=>c.code===selected)))}}
function point(e){const r=canvas.getBoundingClientRect(),layout=canvas.sheetLayout;return {x:Math.floor(((e.clientX-r.left)*canvas.width/r.width-layout.x)/layout.cell),y:Math.floor(((e.clientY-r.top)*canvas.height/r.height-layout.y)/layout.cell)}}function inside(p){return p.x>=0&&p.y>=0&&p.x<draft.size&&p.y<draft.size}
function apply(p){if(!inside(p))return;const next=tool==='erase'?null:selected;if(tool!=='erase')ensureColor();if(draft.grid[p.y][p.x]===next)return;draft.grid[p.y][p.x]=next;mark()}
function line(a,b){const steps=Math.max(Math.abs(a.x-b.x),Math.abs(a.y-b.y));for(let i=0;i<=steps;i++){const t=steps?i/steps:0;apply({x:Math.round(a.x+(b.x-a.x)*t),y:Math.round(a.y+(b.y-a.y)*t)})}}
canvas.onpointerdown=e=>{if(e.button!==0||!e.isPrimary)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);if(tool==='hand'){panning={x:e.clientX,y:e.clientY,left:viewport.scrollLeft,top:viewport.scrollTop};canvas.style.cursor='grabbing';return}const p=point(e);if(!inside(p))return;if(tool==='pick'){const code=draft.grid[p.y][p.x];if(code)chooseColor(code);return}snapshot();if(tool==='fill'){ensureColor();const target=draft.grid[p.y][p.x];if(target!==selected){const q=[p];while(q.length){const v=q.pop();if(!inside(v)||draft.grid[v.y][v.x]!==target)continue;draft.grid[v.y][v.x]=selected;q.push({x:v.x-1,y:v.y},{x:v.x+1,y:v.y},{x:v.x,y:v.y-1},{x:v.x,y:v.y+1})}mark()}update();return}stroke=true;lastCell=p;apply(p);update()};
canvas.onpointermove=e=>{const p=point(e);if(inside(p))$('#cellStatus').textContent='第 '+(p.y+1)+' 行 · 第 '+(p.x+1)+' 列 · '+(label(currentPalette()[draft.grid[p.y][p.x]])||'空白');if(panning){viewport.scrollLeft=panning.left-(e.clientX-panning.x);viewport.scrollTop=panning.top-(e.clientY-panning.y);return}if(stroke&&inside(p)){line(lastCell,p);lastCell=p;update()}};canvas.onpointerup=canvas.onpointercancel=canvas.onlostpointercapture=()=>{stroke=false;lastCell=null;panning=null;canvas.style.cursor=tool==='hand'?'grab':tool==='pen'?'default':'crosshair'};
$('#undo').onclick=()=>{if(!history.length)return;future.push(clone(draft.grid));draft.grid=history.pop();mark();update()};$('#redo').onclick=()=>{if(!future.length)return;history.push(clone(draft.grid));draft.grid=future.pop();mark();update()};
$('#name').oninput=e=>{draft.name=e.target.value;mark();redraw()};$('#author').oninput=e=>{draft.author=e.target.value;mark();redraw()};$('#description').oninput=e=>{draft.description=e.target.value;mark()};$('#size').onchange=e=>{const n=Number(e.target.value);if(stats(draft).total&&!confirm('改变板型将清空当前编辑副本，已保存的底稿不变。继续吗？')){e.target.value=draft.size;return}draft.size=n;draft.grid=Array.from({length:n},()=>Array(n).fill(null));history=[];future=[];mark();update()};$('#export').onclick=()=>exportPng(draft,$('#codes').checked);
$('#save').onclick=async()=>{if(!draft.name.trim()){toast('请填写图纸名称');$('#name').focus();return}const button=$('#save');button.disabled=true;const mode=await chooseSaveMode(original);if(!mode){button.disabled=false;return}button.textContent='正在保存…';try{const saved=await mutation(mode==='overwrite'?'PUT':'POST',{...draft,id:original?.id,name:draft.name.trim(),sourceId:original?.id||null});dirty=false;await loadLibrary();const next='preview?id='+encodeURIComponent(saved.id);if(location.hash==='#'+next)route();else location.hash=next;toast(mode==='overwrite'?'已覆盖保存当前图纸':'已另存为新图，原图仍在列表中')}catch(e){toast(e.message);button.disabled=false;button.textContent='保存图纸'}};update();
}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});document.addEventListener('click',e=>{const link=e.target.closest('a');if(dirty&&link&&link.target!=='_blank'){if(!confirm('当前修改尚未保存，确定离开吗？')){e.preventDefault();return}dirty=false}});window.addEventListener('hashchange',route);
(async()=>{try{try{const r=await fetch('/api/capabilities',{cache:'no-store'});if(r.ok)canWrite=(await r.json()).sourceWrite===true}catch{}await Promise.all([loadLibrary(),xhsEmojiReady]);route()}catch(e){app.innerHTML='<div class="errorBox"><h1>暂时无法读取图纸</h1><p>'+esc(e.message)+'</p><button onclick="location.reload()">重新加载</button></div>'}})();

function confirmDelete(name){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='actionDialog';dialog.innerHTML='<h2>删除这张图纸？</h2><p>将从列表和源码中移除「'+esc(name)+'」。已保存的新版本不受影响。</p><div class="actions"><button data-cancel>取消</button><button class="danger" data-confirm>删除图纸</button></div>';document.body.append(dialog);let result=false;dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.querySelector('[data-confirm]').onclick=()=>{result=true;dialog.close()};dialog.onclose=()=>{dialog.remove();resolve(result)};dialog.showModal()})}
function showExport(baseCanvas,name){
 const dialog=document.createElement('dialog');dialog.className='actionDialog exportDialog';
 dialog.innerHTML='<div class="sectionTitle"><h2>导出图纸</h2><div class="exportActions"><a class="button primary" download>保存 PNG 图片</a><button data-close aria-label="关闭导出预览">关闭</button></div></div><label class="watermarkOption"><input type="checkbox" checked>添加 30° 平铺水印</label><p class="muted">@麦姬大人（拼豆版） · 取消勾选可导出无平铺水印的图片。</p><div class="exportImageArea"><img alt="导出的拼豆图纸"></div>';
 let url=null,revision=0,closed=false;const checkbox=dialog.querySelector('input'),img=dialog.querySelector('img'),link=dialog.querySelector('a');link.download=name+'.png';
 function update(){
  const current=++revision;link.removeAttribute('href');link.setAttribute('aria-disabled','true');
  const canvas=document.createElement('canvas');canvas.width=baseCanvas.width;canvas.height=baseCanvas.height;const ctx=canvas.getContext('2d');ctx.drawImage(baseCanvas,0,0);
  if(checkbox.checked){ctx.save();ctx.translate(canvas.width/2,canvas.height/2);ctx.rotate(-Math.PI/6);ctx.font='22px -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif';ctx.fillStyle='rgba(80,80,80,0.22)';ctx.textAlign='center';ctx.textBaseline='middle';const extent=Math.hypot(canvas.width,canvas.height)/2;for(let y=-extent;y<=extent;y+=150)for(let x=-extent;x<=extent;x+=340)ctx.fillText('@麦姬大人（拼豆版）',x,y);ctx.restore()}
  canvas.toBlob(blob=>{if(closed||current!==revision)return;if(!blob){toast('导出失败，请重试');return}const next=URL.createObjectURL(blob);img.src=next;link.href=next;link.removeAttribute('aria-disabled');if(url)URL.revokeObjectURL(url);url=next},'image/png');
 }
 const outside=e=>{const r=dialog.getBoundingClientRect();return e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom};let backdropDown=false;dialog.addEventListener('pointerdown',e=>{backdropDown=e.target===dialog&&outside(e)});dialog.addEventListener('click',e=>{if(backdropDown&&e.target===dialog&&outside(e))dialog.close();backdropDown=false});
 checkbox.onchange=update;dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.onclose=()=>{closed=true;revision++;if(url)URL.revokeObjectURL(url);dialog.remove()};document.body.append(dialog);dialog.showModal();update();
}

function chooseSaveMode(original){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='actionDialog';dialog.innerHTML='<h2>如何保存图纸？</h2><p>'+(original?'覆盖会更新「'+esc(original.name)+'」；另存会保留原图，并在列表新增一张。':'这是新建图纸，没有可覆盖的原图。')+'</p><div class="actions"><button data-cancel>取消</button><button data-overwrite '+(original?'':'disabled')+'>覆盖当前图纸</button><button data-new class="primary">另存为新图</button></div>';let mode=null;dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.querySelector('[data-overwrite]').onclick=()=>{mode='overwrite';dialog.close()};dialog.querySelector('[data-new]').onclick=()=>{mode='new';dialog.close()};dialog.onclose=()=>{dialog.remove();resolve(mode)};document.body.append(dialog);dialog.showModal()})}
